try {
    // Verificar se msg.payload existe
    if (!msg.payload) {
        console.log('❌ Payload vazio recebido');
        return null;
    }

    // Extrair informações do tópico
    var topicParts = msg.topic.split('/');
    var partida = topicParts[1] || 'partida_desconhecida';
    var jogadora = topicParts[3] || 'jogadora_desconhecida';

    // Fazer parse seguro do JSON se for string
    var dados = msg.payload;
    if (typeof msg.payload === 'string') {
        try {
            dados = JSON.parse(msg.payload);
        } catch (e) {
            console.log('❌ Erro ao parsear JSON:', e.message);
            return null;
        }
    }

    // Garantir que os valores numéricos existem
    var distancia = Number(dados.distancia_acumulada) || 0;
    var velocidade = Number(dados.velocidade) || 0;
    var tempo = Number(dados.tempo) || 0;

    // Criar novo payload seguro
    var novoPayload = {
        jogadora: jogadora,
        partida: partida,
        distancia_acumulada: distancia,
        velocidade: velocidade,
        tempo: tempo,
        timestamp: new Date().toISOString(),
        id_jogadora: dados.id_jogadora || jogadora,
        partida_id: dados.partida || partida
    };

    // Log de sucesso
    console.log('✅ Dados processados com SUCESSO:');
    console.log('Jogadora:', jogadora);
    console.log('Distância:', distancia.toFixed(2) + 'm');
    console.log('Velocidade:', velocidade.toFixed(2) + 'm/s');
    console.log('Tempo:', tempo + 's');

    msg.payload = novoPayload;
    return msg;

} catch (error) {
    console.log('❌ ERRO no processamento:', error.message);
    console.log('Payload recebido:', msg.payload);
    return null;
}

try {
    var dados = msg.payload;

    if (!dados) {
        console.log('❌ Dados vazios para dashboard');
        return [null, null, null];
    }

    // Criar múltiplas mensagens para diferentes componentes
    var mensagens = [];

    // 1. Para o gráfico de distância
    var msgDistancia = {};
    msgDistancia.topic = "distancia";
    msgDistancia.payload = {
        label: dados.jogadora,
        value: dados.distancia_acumulada,
        series: ["Distância"],
        data: [[dados.distancia_acumulada]],
        labels: [new Date(dados.timestamp).toLocaleTimeString()]
    };

    // 2. Para o gauge de velocidade (APENAS o valor numérico)
    var msgVelocidade = {};
    msgVelocidade.payload = dados.velocidade; // APENAS o número

    // 3. Para o template do dashboard
    var msgTemplate = {};
    msgTemplate.payload = {
        jogadora: dados.jogadora,
        partida: dados.partida,
        distancia: dados.distancia_acumulada.toFixed(2),
        velocidade: dados.velocidade.toFixed(2),
        tempo: dados.tempo,
        timestamp: new Date(dados.timestamp).toLocaleTimeString()
    };

    return [msgDistancia, msgVelocidade, msgTemplate];

} catch (error) {
    console.log('❌ ERRO no dashboard:', error.message);
    return [null, null, null];
}
